using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Windows.Forms;
namespace BF4Bots {public static class UnifiedTests {
 static string Root=Environment.GetEnvironmentVariable("BF4_CENTRAL_TEST_ROOT")??"C:\\Program Files\\EA Games\\Battlefield 4";
 public static int Run(string report){var log=new List<string>();try{var words=new[]{"mapList.add","XP0_Metro","ConquestLarge0","2","áé 日本語"};var packet=Rcon.Encode(42,words);if(!words.SequenceEqual(Rcon.Decode(packet)))throw new Exception("Falha no pacote RCON");log.Add("PASS codificação/decodificação RCON com UTF-8");bool rejected=false;try{Rcon.Decode(packet.Take(packet.Length-1).ToArray());}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Aceitou pacote incompleto");log.Add("PASS rejeita pacote incompleto");if(BitConverter.ToUInt32(packet,4)!=packet.Length||BitConverter.ToUInt32(packet,0)!=42)throw new Exception("Cabeçalho incorreto");log.Add("PASS cabeçalho e sequência RCON");var catalog=MapOption.Load(Root);if(catalog.Count<30||!catalog.Any(m=>m.Id=="XP0_Metro"&&m.Modes.Contains("ConquestLarge0")))throw new Exception("Catálogo incompleto");if(catalog[0].Id!="MP_Prison")throw new Exception("Locker não está priorizado");log.Add("PASS catálogo embutido: "+catalog.Count+" mapas; Locker primeiro");var a=new List<RotationEntry>{new RotationEntry{Map="XP0_Metro",Mode="ConquestLarge0",Rounds=1}};var b=new List<RotationEntry>{new RotationEntry{Map="XP0_Metro",Mode="ConquestLarge0",Rounds=2}};if(Rcon.Same(a,b)||!Rcon.Same(a,a))throw new Exception("Comparação de rotações incorreta");log.Add("PASS detecção de conflito da rotação");var exclusive=MapNow.Exclusive(new RotationEntry{Map="MP_Prison",Mode="ConquestLarge0",Rounds=1});if(exclusive.Count!=1||exclusive[0].Map.StartsWith("XP"))throw new Exception("Rotação imediata contém expansão indevida");log.Add("PASS jogo imediato usa apenas Locker, sem mapas DLC");FriendsTests.Run();log.Add("PASS convites LAN, validade/IP, pelotão cheio, readback, espera e mudanças de time/pelotão");RotationMock.Run();log.Add("PASS salvar, carregar mapa, renomear, reaproveitar mapa ativo, rejeitar conflito e restaurar falha em servidor simulado");var ordered=MapNow.First(new List<RotationEntry>{a[0],b[0]},new RotationEntry{Map="XP0_Metro",Mode="ConquestLarge0",Rounds=3});if(ordered.Count!=1||ordered[0].Rounds!=3)throw new Exception("Mapa selecionado não ficou primeiro sem duplicar");log.Add("PASS mapa escolhido priorizado na rotação, sem duplicação; arquivo local e rollback de arquivo/runtime verificados");Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var form=new Central(Root,false)){form.Show();Application.DoEvents();var all=form.Controls.Cast<Control>().SelectMany(c=>c.Controls.Cast<Control>()).OfType<TabControl>().First();if(all.TabCount!=4)throw new Exception("Abas ausentes");all.SelectedIndex=2;Application.DoEvents();var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var type=typeof(Central);var available=(ListView)type.GetField("available",flags).GetValue(form);var rotation=(ListView)type.GetField("rotation",flags).GetValue(form);type.GetField("draft",flags).SetValue(form,new List<RotationEntry>{new RotationEntry{Map="XP0_Oman",Mode="ConquestLarge0",Rounds=1},new RotationEntry{Map="MP_Prison",Mode="ConquestLarge0",Rounds=1}});type.GetMethod("DrawRotation",flags).Invoke(form,null);rotation.Items[1].Selected=true;Application.DoEvents();var chosen=(RotationEntry)type.GetField("selectedChoice",flags).GetValue(form);if(chosen.Map!="MP_Prison"||available.SelectedItems.Count!=0)throw new Exception("Seleção direita não escolheu Locker");var naval=available.Items.Cast<ListViewItem>().First(x=>((MapOption)x.Tag).Id=="MP_Naval");naval.Selected=true;Application.DoEvents();chosen=(RotationEntry)type.GetField("selectedChoice",flags).GetValue(form);if(chosen.Map!="MP_Naval"||rotation.SelectedItems.Count!=0)throw new Exception("Seleções das duas listas ficaram ambíguas");log.Add("PASS escolha entre as duas listas é única e explícita");foreach(TabPage page in all.TabPages){all.SelectedTab=page;Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(Path.Combine(Path.GetDirectoryName(report),"central-"+all.SelectedIndex+".png"));}}form.ClientSize=new Size(1060,810);Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(Path.Combine(Path.GetDirectoryName(report),"central-small.png"));}form.Close();}log.Add("PASS quatro abas renderizadas e tamanho mínimo, sem alterar a instalação");File.WriteAllLines(report,log,Encoding.UTF8);return 0;}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(report,log,Encoding.UTF8);return 1;}}
 public static int RecoverRotation(string report){try{var cfg=Settings.Read(Root);using(var r=new Rcon()){r.Connect(Settings.Get(cfg,"RconHost","127.0.0.1"),Int32.Parse(Settings.Get(cfg,"RconPort","25210")),Settings.Get(cfg,"RconPassword",""));var raw=r.Command("mapList.list");r.Command("mapList.load");var loaded=r.Maps();File.WriteAllLines(report,new[]{"Antes, resposta bruta: "+String.Join(" | ",raw),"Depois de mapList.load: "+loaded.Count+" entradas",String.Join("\r\n",loaded.Select(x=>x.Signature))},Encoding.UTF8);}return 0;}catch(Exception ex){File.WriteAllText(report,"FAIL "+ex,Encoding.UTF8);return 1;}}
 public static int LoadMapLive(string report){try{var c=Settings.Read(Root);using(var r=new Rcon()){r.Connect(Settings.Get(c,"RconHost","127.0.0.1"),Int32.Parse(Settings.Get(c,"RconPort","25210")),Settings.Get(c,"RconPassword",""));var before=r.Maps();var choice=new RotationEntry{Map="MP_Prison",Mode="ConquestLarge0",Rounds=1};int index=before.FindIndex(x=>x.Map==choice.Map&&x.Mode==choice.Mode);if(index<0)throw new Exception("Mapa de teste não cadastrado; nenhuma lista foi alterada.");MapNow.SwitchAndWait(r,choice,"Offline - Operation Locker",index);var info=r.Command("serverInfo");File.WriteAllLines(report,new[]{"PASS mapa ativo confirmado: "+info[5],"PASS modo confirmado: "+info[4],"PASS nome confirmado: "+info[1],"PASS rotação preservada: "+Rcon.Same(before,r.Maps()),"Teste usa o índice já cadastrado; não alterou o arquivo de rotação."},Encoding.UTF8);}return 0;}catch(Exception ex){File.WriteAllText(report,"FAIL "+ex,Encoding.UTF8);return 1;}}
 public static int Live(string report){try{var c=Settings.Read(Root);using(var r=new Rcon()){r.Connect(Settings.Get(c,"RconHost","127.0.0.1"),Int32.Parse(Settings.Get(c,"RconPort","25210")),Settings.Get(c,"RconPassword",""));var info=r.Command("serverInfo");var maps=r.Maps();File.WriteAllLines(report,new[]{"PASS autenticação RCON com desafio/hash","PASS serverInfo: "+String.Join(" | ",info.Take(6)),"PASS leitura da rotação: "+maps.Count+" mapas","Nenhum comando de modificação ou troca de mapa foi enviado."},Encoding.UTF8);}return 0;}catch(Exception ex){File.WriteAllText(report,"FAIL "+ex,Encoding.UTF8);return 1;}}
}}
